"""Cross-phase correction sub-module.

A *correction* is the user revising a value they already provided earlier in the
conversation ("I meant the Freedom card", "it's damaged, not stolen", "make it
rush") while the conversation has already moved to a later phase.

The mechanism is split into:

- :mod:`.discovery` — per-turn discovery of which memory items are correctable.
- :mod:`.coercion` — value coercion + producer re-invoke argument helpers.
- :mod:`.replay` — pure stack-rewind / clear-set helpers.
- :mod:`.executor` — :class:`CorrectionExecutor`, the dispatch + replay drivers.

The discovery and pure helpers are import-light so both the tool-schema builder
and the dispatcher can depend on them.
"""

from rasa.mantle.orchestration.correction.coercion import (
    coerce_to_field_type,
    reinvoke_arguments,
)
from rasa.mantle.orchestration.correction.discovery import (
    find_correctable_fields,
    is_autonomous_skill,
)
from rasa.mantle.orchestration.correction.executor import CorrectionExecutor
from rasa.mantle.orchestration.correction.models import CorrectableMemoryItem
from rasa.mantle.orchestration.correction.replay import (
    build_rewound_stack,
    reconstruct_stack_for_reentry,
    slots_to_clear_after_rewind,
)

__all__ = [
    "CorrectableMemoryItem",
    "CorrectionExecutor",
    "build_rewound_stack",
    "coerce_to_field_type",
    "find_correctable_fields",
    "is_autonomous_skill",
    "reconstruct_stack_for_reentry",
    "reinvoke_arguments",
    "slots_to_clear_after_rewind",
]
